 1→/**
 2→ * @cipherbox/crypto - Device Registry Types
 3→ *
 4→ * Type definitions for the encrypted device registry stored on IPFS/IPNS.
 5→ * The registry tracks authenticated devices with rich metadata and supports
 6→ * cross-device approval (Phase 12.4).
 7→ */
 8→
 9→/** Authorization status for a device in the registry */
10→export type DeviceAuthStatus = 'pending' | 'authorized' | 'revoked';
11→
12→/** Platform identifier for a device */
13→export type DevicePlatform = 'web' | 'macos' | 'linux' | 'windows';
14→
15→/**
16→ * Individual device entry in the registry.
17→ *
18→ * Each entry represents a physical device that has authenticated
19→ * with the user's CipherBox account.
20→ */
21→export type DeviceEntry = {
22→  /** SHA-256 hash of device's Ed25519 public key (hex) */
23→  deviceId: string;
24→  /** Device's Ed25519 public key (hex) - for future key exchange in Phase 12.4 */
25→  publicKey: string;
26→  /** Human-readable device name (e.g., "Chrome on macOS") */
27→  name: string;
28→  /** Platform identifier */
29→  platform: DevicePlatform;
30→  /** App version string (e.g., "0.2.0") */
31→  appVersion: string;
32→  /** Device model or OS version (e.g., "macOS 15.2", "Chrome 123") */
33→  deviceModel: string;
34→  /** SHA-256 hash of IP address at registration (hex, privacy-preserving) */
35→  ipHash: string;
36→  /** Authorization status */
37→  status: DeviceAuthStatus;
38→  /** When device was first registered (Unix ms) */
39→  createdAt: number;
40→  /** Last time device synced with registry (Unix ms) */
41→  lastSeenAt: number;
42→  /** When device was revoked (Unix ms, null if not revoked) */
43→  revokedAt: number | null;
44→  /** Device ID of the device that performed revocation (null if not revoked) */
45→  revokedBy: string | null;
46→};
47→
48→/**
49→ * The full device registry.
50→ *
51→ * Encrypted as a single JSON blob with the user's publicKey via ECIES,
52→ * then stored on IPFS and referenced by a dedicated IPNS name.
53→ */
54→export type DeviceRegistry = {
55→  /** Schema version for future migrations */
56→  version: 'v1';
57→  /** Monotonically increasing update counter */
58→  sequenceNumber: number;
59→  /** Array of all device entries (including revoked, for audit trail) */
60→  devices: DeviceEntry[];
61→};
62→

 1→/**
 2→ * @cipherbox/crypto - Registry IPNS Key Derivation
 3→ *
 4→ * Derives a deterministic Ed25519 IPNS keypair for the device registry
 5→ * from the user's secp256k1 privateKey using HKDF-SHA256.
 6→ *
 7→ * Derivation path:
 8→ *   secp256k1 privateKey (32 bytes)
 9→ *     -> HKDF-SHA256(salt="CipherBox-v1", info="cipherbox-device-registry-ipns-v1")
10→ *     -> 32-byte Ed25519 seed
11→ *     -> Ed25519 keypair
12→ *     -> IPNS name (k51...)
13→ *
14→ * This enables any authenticated session with the user's privateKey
15→ * to discover the registry IPNS name without backend assistance.
16→ */
17→
18→import { deriveKey } from '../keys/derive';
19→import * as ed from '@noble/ed25519';
20→import { deriveIpnsName } from '../ipns/derive-name';
21→import { CryptoError } from '../types';
22→import { SECP256K1_PRIVATE_KEY_SIZE } from '../constants';
23→
24→const REGISTRY_HKDF_SALT = new TextEncoder().encode('CipherBox-v1');
25→const REGISTRY_HKDF_INFO = new TextEncoder().encode('cipherbox-device-registry-ipns-v1');
26→
27→/**
28→ * Derive the deterministic Ed25519 IPNS keypair for the device registry.
29→ *
30→ * Given the same secp256k1 privateKey, this always produces the same
31→ * IPNS name, enabling discovery from any device.
32→ *
33→ * @param userPrivateKey - 32-byte secp256k1 private key
34→ * @returns Ed25519 keypair and IPNS name for the registry
35→ * @throws CryptoError if the private key is not 32 bytes
36→ */
37→export async function deriveRegistryIpnsKeypair(userPrivateKey: Uint8Array): Promise<{
38→  privateKey: Uint8Array;
39→  publicKey: Uint8Array;
40→  ipnsName: string;
41→}> {
42→  // Validate input key length
43→  if (userPrivateKey.length !== SECP256K1_PRIVATE_KEY_SIZE) {
44→    throw new CryptoError('Invalid private key size for registry derivation', 'INVALID_KEY_SIZE');
45→  }
46→
47→  // 1. HKDF: secp256k1 privateKey -> 32-byte Ed25519 seed
48→  const ed25519Seed = await deriveKey({
49→    inputKey: userPrivateKey,
50→    salt: REGISTRY_HKDF_SALT,
51→    info: REGISTRY_HKDF_INFO,
52→    outputLength: 32,
53→  });
54→
55→  // 2. Derive Ed25519 public key from seed (deterministic)
56→  const ed25519PublicKey = await ed.getPublicKeyAsync(ed25519Seed);
57→
58→  // 3. Derive IPNS name from Ed25519 public key (k51... format)
59→  const ipnsName = await deriveIpnsName(ed25519PublicKey);
60→
61→  return {
62→    privateKey: ed25519Seed,
63→    publicKey: ed25519PublicKey,
64→    ipnsName,
65→  };
66→}
67→

 1→/**
 2→ * @cipherbox/crypto - Device Registry Encryption
 3→ *
 4→ * ECIES encryption/decryption for the device registry blob.
 5→ * Uses the same wrapKey/unwrapKey primitives as folder key wrapping.
 6→ *
 7→ * Note: wrapKey/unwrapKey handle arbitrary-length data (not just 32-byte keys).
 8→ * eciesjs internally uses AES-256-GCM for the symmetric portion, so any
 9→ * length payload works. Overhead is ~97 bytes (65 ephemeral pubkey + 16 nonce + 16 tag).
10→ * A 10KB registry produces ~10.1KB ciphertext.
11→ */
12→
13→import { wrapKey } from '../ecies/encrypt';
14→import { unwrapKey } from '../ecies/decrypt';
15→import { validateDeviceRegistry } from './schema';
16→import { CryptoError } from '../types';
17→import { clearBytes } from '../utils/memory';
18→import type { DeviceRegistry } from './types';
19→
20→/**
21→ * Encrypt the device registry for IPFS storage.
22→ *
23→ * Serializes the registry to JSON and encrypts with ECIES using
24→ * the user's secp256k1 publicKey. Only the holder of the corresponding
25→ * privateKey can decrypt it.
26→ *
27→ * @param registry - The device registry to encrypt
28→ * @param userPublicKey - 65-byte uncompressed secp256k1 public key
29→ * @returns Encrypted registry blob
30→ */
31→export async function encryptRegistry(
32→  registry: DeviceRegistry,
33→  userPublicKey: Uint8Array
34→): Promise<Uint8Array> {
35→  const plaintext = new TextEncoder().encode(JSON.stringify(registry));
36→  try {
37→    return await wrapKey(plaintext, userPublicKey);
38→  } finally {
39→    clearBytes(plaintext);
40→  }
41→}
42→
43→/**
44→ * Decrypt the device registry from IPFS storage.
45→ *
46→ * Decrypts with ECIES using the user's secp256k1 privateKey,
47→ * parses the JSON, and validates the schema.
48→ *
49→ * @param encrypted - ECIES-encrypted registry blob from IPFS
50→ * @param userPrivateKey - 32-byte secp256k1 private key
51→ * @returns Validated DeviceRegistry
52→ * @throws CryptoError if decryption or validation fails
53→ */
54→export async function decryptRegistry(
55→  encrypted: Uint8Array,
56→  userPrivateKey: Uint8Array
57→): Promise<DeviceRegistry> {
58→  const plaintext = await unwrapKey(encrypted, userPrivateKey);
59→  try {
60→    const json = new TextDecoder().decode(plaintext);
61→    const parsed = JSON.parse(json);
62→    return validateDeviceRegistry(parsed);
63→  } catch (error) {
64→    if (error instanceof CryptoError) throw error;
65→    throw new CryptoError('Registry decryption produced invalid data', 'DECRYPTION_FAILED');
66→  } finally {
67→    clearBytes(plaintext);
68→  }
69→}
70→

  1→/**
  2→ * @cipherbox/crypto - Device Registry Schema Validation
  3→ *
  4→ * Runtime validation for DeviceRegistry JSON after decryption.
  5→ * Uses manual checks consistent with existing codebase patterns
  6→ * (see folder/metadata.ts validateFolderMetadata).
  7→ */
  8→
  9→import { CryptoError } from '../types';
 10→import type { DeviceRegistry, DeviceAuthStatus, DevicePlatform } from './types';
 11→
 12→const VALID_STATUSES: DeviceAuthStatus[] = ['pending', 'authorized', 'revoked'];
 13→const VALID_PLATFORMS: DevicePlatform[] = ['web', 'macos', 'linux', 'windows'];
 14→const HEX_REGEX = /^[0-9a-fA-F]+$/;
 15→
 16→/**
 17→ * Validate a parsed JSON object as a DeviceRegistry.
 18→ *
 19→ * Throws CryptoError with code 'DECRYPTION_FAILED' on validation failure
 20→ * to avoid leaking schema details to attackers.
 21→ *
 22→ * @param data - Unknown parsed JSON data
 23→ * @returns Validated DeviceRegistry
 24→ * @throws CryptoError if validation fails
 25→ */
 26→export function validateDeviceRegistry(data: unknown): DeviceRegistry {
 27→  if (typeof data !== 'object' || data === null) {
 28→    throw new CryptoError('Invalid registry format', 'DECRYPTION_FAILED');
 29→  }
 30→
 31→  const obj = data as Record<string, unknown>;
 32→
 33→  // Validate version
 34→  if (obj.version !== 'v1') {
 35→    throw new CryptoError('Invalid registry format', 'DECRYPTION_FAILED');
 36→  }
 37→
 38→  // Validate sequenceNumber
 39→  if (
 40→    typeof obj.sequenceNumber !== 'number' ||
 41→    !Number.isInteger(obj.sequenceNumber) ||
 42→    obj.sequenceNumber < 0
 43→  ) {
 44→    throw new CryptoError('Invalid registry format', 'DECRYPTION_FAILED');
 45→  }
 46→
 47→  // Validate devices array
 48→  if (!Array.isArray(obj.devices)) {
 49→    throw new CryptoError('Invalid registry format', 'DECRYPTION_FAILED');
 50→  }
 51→
 52→  // Validate each device entry
 53→  for (const device of obj.devices) {
 54→    validateDeviceEntry(device);
 55→  }
 56→
 57→  return data as DeviceRegistry;
 58→}
 59→
 60→/**
 61→ * Validate an individual device entry.
 62→ */
 63→function validateDeviceEntry(data: unknown): void {
 64→  if (typeof data !== 'object' || data === null) {
 65→    throw new CryptoError('Invalid registry format', 'DECRYPTION_FAILED');
 66→  }
 67→
 68→  const entry = data as Record<string, unknown>;
 69→
 70→  // Required string fields
 71→  const requiredStrings = [
 72→    'deviceId',
 73→    'publicKey',
 74→    'name',
 75→    'platform',
 76→    'appVersion',
 77→    'deviceModel',
 78→    'ipHash',
 79→    'status',
 80→  ];
 81→  for (const field of requiredStrings) {
 82→    if (typeof entry[field] !== 'string') {
 83→      throw new CryptoError('Invalid registry format', 'DECRYPTION_FAILED');
 84→    }
 85→  }
 86→
 87→  // Hex format + length validation for cryptographic fields
 88→  const deviceId = entry.deviceId as string;
 89→  if (deviceId.length !== 64 || !HEX_REGEX.test(deviceId)) {
 90→    throw new CryptoError('Invalid registry format', 'DECRYPTION_FAILED');
 91→  }
 92→
 93→  const publicKey = entry.publicKey as string;
 94→  if (publicKey.length !== 64 || !HEX_REGEX.test(publicKey)) {
 95→    throw new CryptoError('Invalid registry format', 'DECRYPTION_FAILED');
 96→  }
 97→
 98→  const ipHash = entry.ipHash as string;
 99→  if (ipHash.length !== 64 || !HEX_REGEX.test(ipHash)) {
100→    throw new CryptoError('Invalid registry format', 'DECRYPTION_FAILED');
101→  }
102→
103→  // Max length for free-text fields
104→  if ((entry.name as string).length > 200) {
105→    throw new CryptoError('Invalid registry format', 'DECRYPTION_FAILED');
106→  }
107→  if ((entry.appVersion as string).length > 50) {
108→    throw new CryptoError('Invalid registry format', 'DECRYPTION_FAILED');
109→  }
110→  if ((entry.deviceModel as string).length > 200) {
111→    throw new CryptoError('Invalid registry format', 'DECRYPTION_FAILED');
112→  }
113→
114→  // Validate status is a known value
115→  if (!VALID_STATUSES.includes(entry.status as DeviceAuthStatus)) {
116→    throw new CryptoError('Invalid registry format', 'DECRYPTION_FAILED');
117→  }
118→
119→  // Validate platform is a known value
120→  if (!VALID_PLATFORMS.includes(entry.platform as DevicePlatform)) {
121→    throw new CryptoError('Invalid registry format', 'DECRYPTION_FAILED');
122→  }
123→
124→  // Validate timestamp fields
125→  if (typeof entry.createdAt !== 'number' || typeof entry.lastSeenAt !== 'number') {
126→    throw new CryptoError('Invalid registry format', 'DECRYPTION_FAILED');
127→  }
128→
129→  // Validate nullable fields
130→  if (entry.revokedAt !== null && typeof entry.revokedAt !== 'number') {
131→    throw new CryptoError('Invalid registry format', 'DECRYPTION_FAILED');
132→  }
133→  if (entry.revokedBy !== null && typeof entry.revokedBy !== 'string') {
134→    throw new CryptoError('Invalid registry format', 'DECRYPTION_FAILED');
135→  }
136→}
