 1→/**
 2→ * @cipherbox/crypto - Folder Metadata Types
 3→ *
 4→ * Type definitions for encrypted folder metadata stored in IPNS records.
 5→ * v2 schema with per-file IPNS pointers (FilePointer children).
 6→ */
 7→
 8→import type { FilePointer } from '../file/types';
 9→
10→/**
11→ * Decrypted folder metadata structure (v2).
12→ * The entire FolderMetadata object is encrypted as a single blob with AES-256-GCM.
13→ * Children are FolderEntry (subfolders) or FilePointer (slim IPNS references).
14→ */
15→export type FolderMetadata = {
16→  /** Schema version */
17→  version: 'v2';
18→  /** Folders and file pointers in this folder */
19→  children: FolderChild[];
20→};
21→
22→/**
23→ * A child entry can be either a folder or a file pointer.
24→ */
25→export type FolderChild = FolderEntry | FilePointer;
26→
27→/**
28→ * Subfolder entry within folder metadata.
29→ * Contains ECIES-wrapped keys for accessing the subfolder.
30→ */
31→export type FolderEntry = {
32→  type: 'folder';
33→  /** UUID for internal reference */
34→  id: string;
35→  /** Folder name (plaintext, since whole metadata is encrypted) */
36→  name: string;
37→  /** IPNS name for this subfolder (k51... format) */
38→  ipnsName: string;
39→  /** Hex-encoded ECIES-wrapped Ed25519 private key for IPNS signing */
40→  ipnsPrivateKeyEncrypted: string;
41→  /** Hex-encoded ECIES-wrapped AES-256 key for decrypting subfolder metadata */
42→  folderKeyEncrypted: string;
43→  /** Creation timestamp (Unix ms) */
44→  createdAt: number;
45→  /** Last modification timestamp (Unix ms) */
46→  modifiedAt: number;
47→};
48→
49→/**
50→ * Encrypted folder metadata for storage/transmission.
51→ * This is what gets uploaded to IPFS and referenced by IPNS.
52→ */
53→export type EncryptedFolderMetadata = {
54→  /** Hex-encoded 12-byte IV for AES-GCM */
55→  iv: string;
56→  /** Base64-encoded AES-GCM ciphertext (includes 16-byte auth tag) */
57→  data: string;
58→};
59→

 1→/**
 2→ * @cipherbox/crypto - Per-File Metadata Types
 3→ *
 4→ * Type definitions for per-file IPNS metadata records.
 5→ * Each file gets its own IPNS record containing encrypted metadata,
 6→ * while the parent folder only stores a slim FilePointer reference.
 7→ */
 8→
 9→/** A single past version of a file. Stores full crypto context for independent decryption. */
10→export type VersionEntry = {
11→  /** IPFS CID of the encrypted file content for this version */
12→  cid: string;
13→  /** Hex-encoded ECIES-wrapped AES-256 key for decrypting this version */
14→  fileKeyEncrypted: string;
15→  /** Hex-encoded IV used for this version's encryption */
16→  fileIv: string;
17→  /** Original file size in bytes (before encryption) */
18→  size: number;
19→  /** When this version was created (Unix ms) -- i.e., when it became a "past" version */
20→  timestamp: number;
21→  /** Encryption mode used for this version */
22→  encryptionMode: 'GCM' | 'CTR';
23→};
24→
25→/**
26→ * Decrypted per-file metadata structure.
27→ * Stored as an encrypted blob in the file's own IPNS record.
28→ * Encrypted with the parent folder's folderKey (NOT the file's own key).
29→ */
30→export type FileMetadata = {
31→  /** Schema version */
32→  version: 'v1';
33→  /** IPFS CID of the encrypted file content */
34→  cid: string;
35→  /** Hex-encoded ECIES-wrapped AES-256 key for decrypting file */
36→  fileKeyEncrypted: string;
37→  /** Hex-encoded IV used for file encryption */
38→  fileIv: string;
39→  /** Original file size in bytes (before encryption) */
40→  size: number;
41→  /** MIME type of the original file */
42→  mimeType: string;
43→  /** Encryption mode (optional for backward compat; defaults to 'GCM') */
44→  encryptionMode?: 'GCM' | 'CTR';
45→  /** Creation timestamp (Unix ms) */
46→  createdAt: number;
47→  /** Last modification timestamp (Unix ms) */
48→  modifiedAt: number;
49→  /** Past versions of this file (newest first). Omitted if no versions exist. */
50→  versions?: VersionEntry[];
51→};
52→
53→/**
54→ * Slim file reference stored in v2 folder metadata.
55→ * Points to a file's own IPNS record instead of embedding all file data inline.
56→ */
57→export type FilePointer = {
58→  type: 'file';
59→  /** UUID for internal reference */
60→  id: string;
61→  /** File name (plaintext, since folder metadata is encrypted) */
62→  name: string;
63→  /** IPNS name of the file's own metadata record */
64→  fileMetaIpnsName: string;
65→  /** Hex-encoded ECIES-wrapped Ed25519 private key for signing this file's IPNS record.
66→   *  Present for files created after the random-key migration. Absent for legacy files
67→   *  whose IPNS key is derived deterministically via HKDF. */
68→  ipnsPrivateKeyEncrypted?: string;
69→  /** Creation timestamp (Unix ms) */
70→  createdAt: number;
71→  /** Last modification timestamp (Unix ms) */
72→  modifiedAt: number;
73→};
74→
75→/**
76→ * Encrypted file metadata for storage/transmission.
77→ * Same format as EncryptedFolderMetadata (hex IV + base64 ciphertext).
78→ */
79→export type EncryptedFileMetadata = {
80→  /** Hex-encoded 12-byte IV for AES-GCM */
81→  iv: string;
82→  /** Base64-encoded AES-GCM ciphertext (includes 16-byte auth tag) */
83→  data: string;
84→};
85→

  1→import { Controller, Post, Get, Body, UseGuards, Request, NotFoundException } from '@nestjs/common';
  2→import { ApiTags, ApiOperation, ApiResponse, ApiBearerAuth } from '@nestjs/swagger';
  3→import { JwtAuthGuard } from '../auth/guards/jwt-auth.guard';
  4→import { VaultService } from './vault.service';
  5→import { InitVaultDto, VaultResponseDto } from './dto/init-vault.dto';
  6→import { VaultExportDto } from './dto/vault-export.dto';
  7→import { QuotaResponseDto } from './dto/quota.dto';
  8→import { RequestWithUser } from '../common/types';
  9→
 10→@ApiTags('Vault')
 11→@ApiBearerAuth()
 12→@UseGuards(JwtAuthGuard)
 13→@Controller('vault')
 14→export class VaultController {
 15→  constructor(private readonly vaultService: VaultService) {}
 16→
 17→  @Post('init')
 18→  @ApiOperation({
 19→    summary: 'Initialize user vault',
 20→    description:
 21→      'Create a new vault with encrypted keys on first sign-in. Returns 409 Conflict if vault already exists.',
 22→  })
 23→  @ApiResponse({
 24→    status: 201,
 25→    description: 'Vault initialized successfully',
 26→    type: VaultResponseDto,
 27→  })
 28→  @ApiResponse({
 29→    status: 401,
 30→    description: 'Unauthorized - JWT token required',
 31→  })
 32→  @ApiResponse({
 33→    status: 409,
 34→    description: 'Conflict - Vault already exists for this user',
 35→  })
 36→  async initializeVault(
 37→    @Request() req: RequestWithUser,
 38→    @Body() dto: InitVaultDto
 39→  ): Promise<VaultResponseDto> {
 40→    return this.vaultService.initializeVault(req.user.id, dto);
 41→  }
 42→
 43→  @Get('export')
 44→  @ApiOperation({
 45→    summary: 'Export vault for independent recovery',
 46→    description:
 47→      'Returns the minimal vault data needed for independent recovery: root IPNS name, encrypted root keys, and derivation hints.',
 48→  })
 49→  @ApiResponse({
 50→    status: 200,
 51→    description: 'Vault export data',
 52→    type: VaultExportDto,
 53→  })
 54→  @ApiResponse({
 55→    status: 401,
 56→    description: 'Unauthorized - JWT token required',
 57→  })
 58→  @ApiResponse({
 59→    status: 404,
 60→    description: 'Not Found - Vault does not exist',
 61→  })
 62→  async exportVault(@Request() req: RequestWithUser): Promise<VaultExportDto> {
 63→    return this.vaultService.getExportData(req.user.id);
 64→  }
 65→
 66→  @Get()
 67→  @ApiOperation({
 68→    summary: 'Get user vault',
 69→    description: 'Retrieve the vault for the authenticated user.',
 70→  })
 71→  @ApiResponse({
 72→    status: 200,
 73→    description: 'Vault retrieved successfully',
 74→    type: VaultResponseDto,
 75→  })
 76→  @ApiResponse({
 77→    status: 401,
 78→    description: 'Unauthorized - JWT token required',
 79→  })
 80→  @ApiResponse({
 81→    status: 404,
 82→    description: 'Not Found - Vault does not exist',
 83→  })
 84→  async getVault(@Request() req: RequestWithUser): Promise<VaultResponseDto> {
 85→    const vault = await this.vaultService.findVault(req.user.id);
 86→    if (!vault) {
 87→      throw new NotFoundException('Vault not found');
 88→    }
 89→    return vault;
 90→  }
 91→
 92→  @Get('quota')
 93→  @ApiOperation({
 94→    summary: 'Get storage quota',
 95→    description: 'Get current storage usage and limits. Limit is 500 MiB (524,288,000 bytes).',
 96→  })
 97→  @ApiResponse({
 98→    status: 200,
 99→    description: 'Quota retrieved successfully',
100→    type: QuotaResponseDto,
101→  })
102→  @ApiResponse({
103→    status: 401,
104→    description: 'Unauthorized - JWT token required',
105→  })
106→  async getQuota(@Request() req: RequestWithUser): Promise<QuotaResponseDto> {
107→    return this.vaultService.getQuota(req.user.id);
108→  }
109→}
110→

  1→import { Injectable, ConflictException, NotFoundException } from '@nestjs/common';
  2→import { InjectRepository } from '@nestjs/typeorm';
  3→import { Repository } from 'typeorm';
  4→import { Vault } from './entities/vault.entity';
  5→import { PinnedCid } from './entities/pinned-cid.entity';
  6→import { FolderIpns } from '../ipns/entities/folder-ipns.entity';
  7→import { User } from '../auth/entities/user.entity';
  8→import { InitVaultDto, VaultResponseDto } from './dto/init-vault.dto';
  9→import { VaultExportDto } from './dto/vault-export.dto';
 10→import { QuotaResponseDto } from './dto/quota.dto';
 11→import { TeeKeyStateService } from '../tee/tee-key-state.service';
 12→import { TeeKeysDto } from '../tee/dto/tee-keys.dto';
 13→
 14→/**
 15→ * Storage quota limit: 500 MiB
 16→ */
 17→export const QUOTA_LIMIT_BYTES = 500 * 1024 * 1024; // 524,288,000 bytes
 18→
 19→@Injectable()
 20→export class VaultService {
 21→  constructor(
 22→    @InjectRepository(Vault)
 23→    private readonly vaultRepository: Repository<Vault>,
 24→    @InjectRepository(PinnedCid)
 25→    private readonly pinnedCidRepository: Repository<PinnedCid>,
 26→    @InjectRepository(FolderIpns)
 27→    private readonly folderIpnsRepository: Repository<FolderIpns>,
 28→    @InjectRepository(User)
 29→    private readonly userRepository: Repository<User>,
 30→    private readonly teeKeyStateService: TeeKeyStateService
 31→  ) {}
 32→
 33→  /**
 34→   * Initialize a new vault for a user
 35→   * Creates the vault with encrypted keys on first sign-in
 36→   *
 37→   * @throws ConflictException if vault already exists for user
 38→   */
 39→  async initializeVault(userId: string, dto: InitVaultDto): Promise<VaultResponseDto> {
 40→    // Check if vault already exists
 41→    const existingVault = await this.vaultRepository.findOne({
 42→      where: { ownerId: userId },
 43→    });
 44→
 45→    if (existingVault) {
 46→      throw new ConflictException('Vault already exists for this user');
 47→    }
 48→
 49→    // Decode hex strings to buffers
 50→    const vault = this.vaultRepository.create({
 51→      ownerId: userId,
 52→      ownerPublicKey: Buffer.from(dto.ownerPublicKey, 'hex'),
 53→      encryptedRootFolderKey: Buffer.from(dto.encryptedRootFolderKey, 'hex'),
 54→      encryptedRootIpnsPrivateKey: Buffer.from(dto.encryptedRootIpnsPrivateKey, 'hex'),
 55→      rootIpnsName: dto.rootIpnsName,
 56→      initializedAt: null,
 57→    });
 58→
 59→    const savedVault = await this.vaultRepository.save(vault);
 60→
 61→    // Create root folder IPNS entry for publish tracking
 62→    // This allows IPNS publishes to work without requiring TEE fields on every publish
 63→    const rootFolderIpns = this.folderIpnsRepository.create({
 64→      userId,
 65→      ipnsName: dto.rootIpnsName,
 66→      latestCid: null, // No content yet
 67→      sequenceNumber: '0',
 68→      encryptedIpnsPrivateKey: null, // TEE key added when TEE is implemented
 69→      keyEpoch: null,
 70→      isRoot: true,
 71→    });
 72→    await this.folderIpnsRepository.save(rootFolderIpns);
 73→
 74→    const teeKeys = await this.teeKeyStateService.getTeeKeysDto();
 75→    return this.toVaultResponse(savedVault, teeKeys);
 76→  }
 77→
 78→  /**
 79→   * Get vault for a user
 80→   *
 81→   * @throws NotFoundException if vault does not exist
 82→   */
 83→  async getVault(userId: string): Promise<VaultResponseDto> {
 84→    const vault = await this.vaultRepository.findOne({
 85→      where: { ownerId: userId },
 86→    });
 87→
 88→    if (!vault) {
 89→      throw new NotFoundException('Vault not found');
 90→    }
 91→
 92→    const teeKeys = await this.teeKeyStateService.getTeeKeysDto();
 93→    return this.toVaultResponse(vault, teeKeys);
 94→  }
 95→
 96→  /**
 97→   * Check if vault exists for user (returns null if not)
 98→   */
 99→  async findVault(userId: string): Promise<VaultResponseDto | null> {
100→    const vault = await this.vaultRepository.findOne({
101→      where: { ownerId: userId },
102→    });
103→
104→    if (!vault) return null;
105→
106→    const teeKeys = await this.teeKeyStateService.getTeeKeysDto();
107→    return this.toVaultResponse(vault, teeKeys);
108→  }
109→
110→  /**
111→   * Get current storage quota usage for a user
112→   */
113→  async getQuota(userId: string): Promise<QuotaResponseDto> {
114→    const result = await this.pinnedCidRepository
115→      .createQueryBuilder('pin')
116→      .select('COALESCE(SUM(pin.size_bytes), 0)', 'total')
117→      .where('pin.user_id = :userId', { userId })
118→      .getRawOne<{ total: string }>();
119→
120→    const usedBytes = parseInt(result?.total ?? '0', 10);
121→    const remainingBytes = Math.max(0, QUOTA_LIMIT_BYTES - usedBytes);
122→
123→    return {
124→      usedBytes,
125→      limitBytes: QUOTA_LIMIT_BYTES,
126→      remainingBytes,
127→    };
128→  }
129→
130→  /**
131→   * Check if user has sufficient quota for additional storage
132→   *
133→   * @returns true if (current usage + additionalBytes) <= quota limit
134→   */
135→  async checkQuota(userId: string, additionalBytes: number): Promise<boolean> {
136→    const quota = await this.getQuota(userId);
137→    return quota.usedBytes + additionalBytes <= QUOTA_LIMIT_BYTES;
138→  }
139→
140→  /**
141→   * Record a pinned CID for quota tracking
142→   * Uses upsert (ON CONFLICT DO NOTHING) for idempotency
143→   */
144→  async recordPin(userId: string, cid: string, sizeBytes: number): Promise<void> {
145→    await this.pinnedCidRepository
146→      .createQueryBuilder()
147→      .insert()
148→      .into(PinnedCid)
149→      .values({
150→        userId,
151→        cid,
152→        sizeBytes: sizeBytes.toString(),
153→      })
154→      .orIgnore() // ON CONFLICT DO NOTHING for idempotency
155→      .execute();
156→  }
157→
158→  /**
159→   * Remove a pinned CID record
160→   * Idempotent - no error if CID not found
161→   */
162→  async recordUnpin(userId: string, cid: string): Promise<void> {
163→    await this.pinnedCidRepository.delete({
164→      userId,
165→      cid,
166→    });
167→  }
168→
169→  /**
170→   * Mark vault as initialized (first file uploaded)
171→   */
172→  async markInitialized(userId: string): Promise<void> {
173→    await this.vaultRepository.update({ ownerId: userId }, { initializedAt: new Date() });
174→  }
175→
176→  /**
177→   * Get export data for independent recovery.
178→   * Returns the minimal set of fields needed to reconstruct the vault:
179→   * root IPNS name + encrypted root keys + derivation hints.
180→   */
181→  async getExportData(userId: string): Promise<VaultExportDto> {
182→    const vault = await this.vaultRepository.findOne({
183→      where: { ownerId: userId },
184→    });
185→
186→    if (!vault) {
187→      throw new NotFoundException('Vault not found');
188→    }
189→
190→    const user = await this.userRepository.findOne({
191→      where: { id: userId },
192→    });
193→
194→    return {
195→      format: 'cipherbox-vault-export',
196→      version: '1.0',
197→      exportedAt: new Date().toISOString(),
198→      rootIpnsName: vault.rootIpnsName,
199→      encryptedRootFolderKey: vault.encryptedRootFolderKey.toString('hex'),
200→      encryptedRootIpnsPrivateKey: vault.encryptedRootIpnsPrivateKey.toString('hex'),
201→      derivationMethod: user ? 'web3auth' : null,
202→    };
203→  }
204→
205→  /**
206→   * Convert Vault entity to response DTO with hex-encoded fields
207→   */
208→  private toVaultResponse(vault: Vault, teeKeys: TeeKeysDto | null = null): VaultResponseDto {
209→    return {
210→      id: vault.id,
211→      ownerPublicKey: vault.ownerPublicKey.toString('hex'),
212→      encryptedRootFolderKey: vault.encryptedRootFolderKey.toString('hex'),
213→      encryptedRootIpnsPrivateKey: vault.encryptedRootIpnsPrivateKey.toString('hex'),
214→      rootIpnsName: vault.rootIpnsName,
215→      createdAt: vault.createdAt,
216→      initializedAt: vault.initializedAt,
217→      teeKeys,
218→    };
219→  }
220→}
